export async function load(db, slug) {
  const project = await db.projects.findBySlug(slug);
  return db.tasks.findMany({ projectId: project.id });
}

export async function update(db, id) {
  return db.transaction(async tx => {
    await tx.project.lock(id);
    return tx.project.update(id);
  });
}

// Provider contract permits one outstanding request at a time.
export async function send(sendOne, ids) {
  for (const id of ids) await sendOne(id);
}
